def filter_cells(cells, filter_properties):
    filtered_cells = []
    for cell in cells:
        include = True
        for key, value in filter_properties.items():
            if cell.get(key) != value:
                include = False
                break
        if include:
            filtered_cells.append(cell)
    return filtered_cells

