def merge_features(dict1, dict2):
    """
    Merge two dictionaries containing various features.

    :param dict1: The first dictionary.
    :param dict2: The second dictionary.
    :return: A merged dictionary with combined values of common keys.
    """
    merged_dict = {}
    for key in dict1:
        merged_dict[key] = dict1[key]
    for key in dict2:
        if key in merged_dict:
            merged_dict[key] = [merged_dict[key], dict2[key]]
        else:
            merged_dict[key] = dict2[key]
    return merged_dict

