def parse_metadata(metadata_list):
    """
    Parse a list of strings representing metadata entries for software development projects.
    Return a dictionary containing the extracted key-value pairs.
    """
    metadata = {}
    for entry in metadata_list:
        try:
            key, value = entry.split(' :: ')
            metadata[key] = value
        except ValueError:
            pass
    return metadata

def extract_keys(json_object):
    """
    Recursively extracts all keys from a JSON object and returns them in a list.

    :param json_object: A JSON object
    :return: A list of all keys present in the object, including nested keys
    """
    keys = []

    if isinstance(json_object, dict):
        for key in json_object.keys():
            keys.append(key)
            keys.extend(extract_keys(json_object[key]))

    elif isinstance(json_object, list):
        for item in json_object:
            keys.extend(extract_keys(item))

    return keys

