def update_orfs(orfs, pid, min_pid, query, subject, blast_result):
    """
    Updates the orfs dictionary based on the following conditions: 
    If pid is greater than or equal to min_pid, then if query is already present in orfs, you should update the dictionary with the subject and its associated blast result. If query is not present, create a new entry for query with the subject and its associated blast result. The function should return the updated orfs dictionary. The structure of the orfs dictionary is as follows: { 'query1': { 'subject1': {'blastresult': blastresult1}, ... }, ... }
    """
    if pid >= min_pid:
        if query in orfs:
            orfs[query][subject] = {'blastresult': blast_result}
        else:
            orfs[query] = {subject: {'blastresult': blast_result}}
    return orfs

