def track_paths(product_path_tuples):
    """
    Takes in a list of tuples where each tuple contains a product name and a path (represented as a list of strings).
    Returns a tuple containing two elements: a list of unique products produced and a dictionary where the keys are product names and the values are lists of paths corresponding to each product.
    """
    products = []
    product_paths = {}

    for product, path in product_path_tuples:
        if product not in products:
            products.append(product)
            product_paths[product] = [path]
        else:
            product_paths[product].append(path)

    return products, product_paths

