def transform_data(data: Dict[str, List[int]]) -> Dict[str, List[int]]:
    """
    This function takes a dictionary of lists as input and returns a new dictionary where each list has been transformed by filtering out values that are less than 10. The output dictionary should maintain the same keys as the input.
