    return {key: [value for value in values if value >= 10] for key, values in data.items()}

def process_command(command, config_file_path, allow_duplicates=False):
  """
  Migrates related items to a specified destination and converts Markdown notes to HTML.
  :param command: Command (either 'migrate' or 'markdown-to-html')
  :param config_file_path: Path to the config file (string)
  :param allow_duplicates: Boolean flag indicating whether to allow duplicates (defaults to False)
  :return: String indicating the result of the operation
  """
  if not config_file_path:
    return "Invalid config path."

  if command == 'migrate':
    if allow_duplicates:
      return 'Migrating items with duplicates allowed.'
    else:
      return 'Migrating items without duplicates.'
  elif command == 'markdown-to-html':
    return 'Converting Markdown notes to HTML.'
  else:
    return 'Invalid command.'

