def pad_list(input_list, target_length):
    """
    Modifies the input list according to the following rules:
    If the list has more elements than the target length, 
    return a new list containing only the first 'target_length' elements from the original list. 
    If the list has fewer elements than the target length,
    return a new list containing all the elements of the original list followed by enough zeros to reach the target length.
    """
    if len(input_list) > target_length:
        return input_list[:target_length]
    else:
        return input_list + [0] * (target_length - len(input_list))

