def process_molecular_graphs(mol_graphs):
    # Initialize a counter for the total number of processed graphs and an empty list for the unique file names
    processed_graphs = 0
    unique_filenames = []

    # Iterate over the list of molecular graphs
    for graph in mol_graphs:
        # Increment the counter for the total number of processed graphs
        processed_graphs += 1

        # Iterate over the list of file names associated with the current graph
        for filename in graph['files']:
            # If the file name is not already in the list of unique file names, add it
            if filename not in unique_filenames:
                unique_filenames.append(filename)

    # Return the tuple with the total number of processed graphs and the list of unique file names
    return (processed_graphs, unique_filenames)

