from typing import List, Tuple, Dict

def parse_migration_operations(operations: List[Tuple[str, str, str, str, str]]) -> Dict[str, List[Tuple[str, str, str]]]:
    """
    Given a list of migration operations represented as tuples, where each tuple contains the operation type ('migrations.AlterField' or 'migrations.CreateModel'), model name, field name, field type, and default value, this function processes the list and returns a dictionary where each key is a model name and the corresponding value is a list of tuples. Each tuple should contain the field name, field type, and default value for that model.

    Args:
        operations (List[Tuple[str, str, str, str, str]]): List of migration operations represented as tuples.

    Returns:
        Dict[str, List[Tuple[str, str, str]]]: Dictionary where each key is a model name and the corresponding value is a list of tuples.
    """
    result = {}

    for operation in operations:
        operation_type, model_name, field_name, field_type, default_value = operation

        if operation_type == 'migrations.AlterField':
            if model_name not in result:
                result[model_name] = []
            result[model_name].append((field_name, field_type, default_value))
        elif operation_type == 'migrations.CreateModel':
            if model_name not in result:
                result[model_name] = []
            result[model_name].append((field_name, field_type, default_value))

    return result

