def version_control(major, minor, patch, action):
    """
    Accepts three integers representing the current major, minor, and patch version numbers, and a string action that can be 'bump_major', 'bump_minor', or 'bump_patch'
    Returns the new version string in the format 'major.minor.patch' after performing the specified action
    If an invalid action is provided, the function should return the current version string without any changes
    """
    if action == "bump_major":
        return f"{major + 1}.0.0"
    elif action == "bump_minor":
        return f"{major}.{minor + 1}.0"
    elif action == "bump_patch":
        return f"{major}.{minor}.{patch + 1}"
    else:
        return f"{major}.{minor}.{patch}"

def process_snmp_mib_data(mib_data: dict) -> dict:
    """
    This function processes SNMP MIB data. The function takes a dictionary containing MIB data as input and returns a new dictionary that includes the imported symbols as keys mapped to their respective string representation and a scalar instance represented as a dictionary with its name and value.
    """
    imported_symbols = {}
    scalar_instance = {}
    for symbol in mib_data['symbols']:
        imported_symbols[symbol] = symbol
    scalar_instance['name'] = mib_data['scalar_instance_name']
    scalar_instance['value'] = mib_data['scalar_instance_value']
    return {'imported_symbols': imported_symbols, 'scalar_instance': scalar_instance}

def update_inventory(inventory, transactions):
    for transaction in transactions:
        product, quantity = transaction
        if product in inventory:
            inventory[product] += quantity
        else:
            inventory[product] = quantity
    return inventory

